// Tiny wrapper around the browser's built-in text-to-speech, used ONLY by the mock agents
// so the demo actually talks. The live agents play their own audio.

const hasTTS = () =>
  typeof window !== 'undefined' && 'speechSynthesis' in window && typeof SpeechSynthesisUtterance !== 'undefined';

let muted = false;
try {
  muted = localStorage.getItem('pawse.muted') === '1';
} catch {
  /* storage unavailable */
}

export const isSpeechMuted = () => muted;

export function setSpeechMuted(m) {
  muted = !!m;
  try {
    localStorage.setItem('pawse.muted', muted ? '1' : '0');
  } catch {
    /* ignore */
  }
  if (muted && hasTTS()) window.speechSynthesis.cancel();
}

/** Rough spoken duration, used for pacing when the voice is muted or unavailable. */
export function estimateMs(text, lang) {
  const per = String(lang).startsWith('zh') ? 210 : 68;
  return Math.max(1200, String(text).length * per);
}

const TAGS = { zh: 'zh-CN', en: 'en-US', de: 'de-DE', hi: 'hi-IN' };

function pickVoice(tag) {
  const voices = window.speechSynthesis.getVoices();
  return voices.find((v) => v.lang === tag) || voices.find((v) => v.lang.toLowerCase().startsWith(tag.slice(0, 2)));
}

/** Call inside a tap so iOS Safari allows speech later on. */
export function primeSpeech() {
  if (!hasTTS()) return;
  try {
    const u = new SpeechSynthesisUtterance(' ');
    u.volume = 0;
    window.speechSynthesis.speak(u);
  } catch {
    /* ignore */
  }
}

export function stopSpeech() {
  if (hasTTS()) window.speechSynthesis.cancel();
}

/**
 * Speak `text`; resolves when finished. speed > 1 (tests / rehearsal) skips the voice.
 * silent: don't play it, just wait as long as it would take (a call running in the background).
 */
export function speak(text, lang, { speed = 1, pitch = 1, rate = 1, silent = false } = {}) {
  const est = estimateMs(text, lang);
  if (speed > 1 || silent || muted || !hasTTS()) return new Promise((r) => setTimeout(r, est / speed));

  return new Promise((resolve) => {
    let done = false;
    const finish = () => {
      if (done) return;
      done = true;
      clearTimeout(guard);
      resolve();
    };
    const guard = setTimeout(finish, est * 2 + 3000); // never hang if the engine stalls
    try {
      const u = new SpeechSynthesisUtterance(text);
      const tag = TAGS[lang] || lang;
      u.lang = tag;
      const v = pickVoice(tag);
      if (v) u.voice = v;
      u.pitch = pitch;
      u.rate = rate;
      u.onend = finish;
      u.onerror = finish;
      window.speechSynthesis.speak(u);
    } catch {
      setTimeout(finish, est);
    }
  });
}
// SLOT 2: clinic search against the Pawse FastAPI backend.
// Endpoint: POST /api/v1/care/requests (same origin; Vite proxies /api to :8765).
// Base URL defaults to ''; override with VITE_CLINIC_SEARCH_URL (e.g. https://pawse.example.com).
//
// Consent: only location sharing is sent (share_location=true, and only when a location exists).
// share_with_ai stays false and the query is a generic string, so no symptoms leave the device
// for a clinic lookup. The backend enforces consent server-side as well.

import { CLINIC_SEARCH_URL } from '../config.js';

const ENDPOINT = '/api/v1/care/requests';

export function haversineKm(a, b) {
  const rad = (d) => (d * Math.PI) / 180;
  const dLat = rad(b.lat - a.lat);
  const dLng = rad(b.lng - a.lng);
  const h = Math.sin(dLat / 2) ** 2 + Math.cos(rad(a.lat)) * Math.cos(rad(b.lat)) * Math.sin(dLng / 2) ** 2;
  return 2 * 6371.0088 * Math.asin(Math.min(1, Math.sqrt(h)));
}

/** Map one backend Clinic to the frontend Clinic. Never invents hours or distance. */
export function mapClinic(c, location) {
  let distanceKm = Number.NaN; // unknown; the page shows a dash
  if (typeof c.distance_km === 'number') distanceKm = c.distance_km;
  else if (location && c.location && typeof c.location.lat === 'number') distanceKm = haversineKm(location, c.location);
  const openUnknown = typeof c.open_now !== 'boolean';
  const out = {
    id: c.id,
    name: c.name,
    address: c.address || '',
    distanceKm,
    openNow: c.open_now === true,
    hoursText: openUnknown ? 'Hours unknown, call to confirm' : (c.open_now ? 'Reported open now by provider, call to confirm' : 'Reported closed by provider'),
  };
  if (openUnknown) out.openUnknown = true;
  if (c.emergency_service === 'provider_reported') out.emergency = true;
  if (typeof c.rating === 'number') out.rating = c.rating;
  if (c.maps_url) out.mapsUrl = c.maps_url;
  if (c.phone) out.phone = c.phone;
  if (/^tel:\+[1-9]\d{6,14}$/.test(c.call_url || '')) out.callUrl = c.call_url;
  out.source = c.source; out.retrievedAt = c.retrieved_at;
  out.reasons = c.reasons || [];
  out.website = c.website;
  return out;
}

export async function liveSearchClinics({ lang = 'en', location = null, triage = null } = {}) {
  if (!location) throw new Error('Location is needed to find nearby clinics (permission denied or unavailable).');
  const body = {
    query: 'Find nearby veterinary clinics for a cat.',
    language: /^[a-z]{2}$/.test(lang) ? lang : 'en',
    location: { lat: location.lat, lng: location.lng },
    share_location: true,
    share_with_ai: false,
  };
  const res = await fetch((CLINIC_SEARCH_URL || '') + ENDPOINT, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify(body),
  });
  if (!res.ok) {
    const error = await res.json().catch(() => ({}));
    throw new Error(typeof error.detail === 'string' ? error.detail : `Clinic search failed (${res.status})`);
  }
  const data = await res.json();
  const raw = Array.isArray(data && data.clinics) ? data.clinics : [];
  if (!raw.length) {
    const why = (data && data.warnings && data.warnings.join(', ')) || (data && data.providers && JSON.stringify(data.providers)) || 'no details';
    throw new Error(`No clinics returned by the backend (clinic provider not configured or unavailable: ${why}).`);
  }
  const clinics = raw.map((c) => mapClinic(c, location));
  // Preserve server ranking (opening status, distance, rating).
  return { clinics };
}
// Live phone agent for Pawse. There is NO telephony: the German script and the numbers come from
// the backend (GET /api/v1/demo/mimi), every AI line is spoken with the same Gradium German voice
// (POST /api/v1/voice/speech, only with explicit consent), and every callee reply and the result
// stay marked `simulated: true`. Nothing is ever dialled or booked. Implements ../contracts.js.
//
// One call = one server-issued call id: the first AI line carries the AI disclosure and the server
// answers with an X-Pawse-Call-Id header; later lines send that id so the server does not repeat
// the disclosure. If Gradium fails (no key, 503, network), the rest of the call uses browser speech
// so the voice never flips back and forth.

import { PHONE_AGENT_URL } from '../config.js';
import { speak, stopSpeech, isSpeechMuted } from './speech.js';

// Must equal DISCLOSURE in pawse/voice.py so the server does not prepend a second greeting.
const DISCLOSURE = 'Guten Tag, hier ist Pawse, die KI-Assistenz im Auftrag der Katzenhalterin oder des Katzenhalters.';
const FIRST_LINE = {
  original: `${DISCLOSURE} Ich bin ein KI-Assistent und kein Mensch.`,
  text: {
    en: 'Hello, this is Pawse, the AI assistant calling on behalf of the cat owner. I am an AI assistant, not a person.',
    zh: '您好，我是 Pawse，受猫主人委托的 AI 助手。我是 AI 助手，不是真人。',
  },
};
const STEP_INDEX = { vet: 2, insurance: 3 };
const T = (en, zh) => ({ en, zh });

const num = (v, d) => (typeof v === 'number' && Number.isFinite(v) ? v : d);

async function fetchStory(base) {
  const res = await fetch(`${base}/api/v1/demo/mimi`);
  if (!res.ok) throw new Error(`demo story unavailable (${res.status})`);
  return res.json();
}

/**
 * Fetches Gradium audio for the AI lines of one call, strictly in order (the first response
 * carries the call id the later ones need). Each line is fetched at most once, so the page can
 * preload the next AI line while the current one plays.
 */
function createGradiumLines(base, voice, state) {
  const cache = new Map();
  let chain = Promise.resolve();
  let callId = null;
  let failed = false;

  const request = async (text) => {
    if (failed || state.ended) return null;
    try {
      const res = await fetch(`${base}/api/v1/voice/speech`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text, language: 'de', voice, share_with_gradium: true, ...(callId ? { call_id: callId } : {}) }),
      });
      if (!res.ok) throw new Error(`speech ${res.status}`);
      const id = res.headers && typeof res.headers.get === 'function' ? res.headers.get('x-pawse-call-id') : null;
      if (id) callId = id;
      return await res.blob();
    } catch {
      failed = true; // stay on browser speech for the rest of this call
      return null;
    }
  };

  return {
    get failed() {
      return failed;
    },
    /** Promise<Blob|null> for line `key`; queued behind every earlier request. */
    fetch(key, text) {
      if (!cache.has(key)) {
        const p = chain.then(() => request(text));
        chain = p;
        cache.set(key, p);
      }
      return cache.get(key);
    },
  };
}

/** Plays one audio blob. Resolves true if it played to the end, false to fall back. */
function playBlob(blob, state) {
  if (!blob || state.ended || typeof Audio === 'undefined' || typeof URL === 'undefined' || !URL.createObjectURL) {
    return Promise.resolve(false);
  }
  return new Promise((resolve) => {
    let url;
    try {
      url = URL.createObjectURL(blob);
    } catch {
      resolve(false);
      return;
    }
    const a = new Audio(url);
    state.audio = a;
    const done = (ok) => {
      if (state.audio === a) state.audio = null;
      try { URL.revokeObjectURL(url); } catch { /* ignore */ }
      resolve(ok);
    };
    a.onended = () => done(true);
    a.onerror = () => done(false);
    try {
      const p = a.play();
      if (p && p.catch) p.catch(() => done(false));
    } catch {
      done(false);
    }
  });
}

function buildVetResult(story, lang, context) {
  const c = story.costs || {};
  return {
    kind: 'appointment',
    time: story.calendar?.appointment || '16:30',
    place: context.clinic?.name || (lang === 'zh' ? '诊所（演示）' : 'Clinic (demo)'),
    estimate: num(c.treatment, 600),
    currency: c.currency || 'CHF',
    note:
      lang === 'zh'
        ? '模拟：这是演示脚本，没有真的打电话，也没有真的预约。上门另加约 150 瑞郎。'
        : 'Simulated: demo script, no real call was made and nothing was booked. A home visit would add about CHF 150.',
    simulated: true,
  };
}

function buildInsuranceResult(story, lang) {
  const c = story.costs || {};
  const deductible = num(c.remaining_deductible, 300);
  const rate = num(c.reimbursement_rate, 0.8);
  const estimate = num(c.treatment, 600);
  const reimbursed = num(c.reimbursed, Math.max(estimate - deductible, 0) * rate);
  const cur = c.currency || 'CHF';
  const zh = lang === 'zh';
  const clinic = num(c.clinic, 385);
  const home = num(c.home, 510);
  return {
    kind: 'coverage',
    covered: true,
    currency: cur,
    deductible,
    rate,
    estimate,
    reimbursed,
    outOfPocket: estimate - reimbursed,
    points: [
      { ok: true, text: zh ? '意外从第一天起就保' : 'Accident covered from day 1' },
      {
        ok: true,
        text: zh
          ? `先付前 ${deductible} 瑞郎，之后报销 ${Math.round(rate * 100)}%`
          : `You pay the first ${cur} ${deductible}, then ${Math.round(rate * 100)}% is reimbursed`,
      },
      { ok: false, text: zh ? '上门费不保' : 'Home visit not covered', ref: 'AVB 1.2' },
      { ok: false, text: zh ? '之后的理疗不保' : 'Physiotherapy not covered', ref: 'AVB 1.2' },
      {
        ok: true,
        text: zh
          ? `估算自付：诊所约 ${cur} ${clinic}，上门约 ${cur} ${home}（含出租车 / 上门费）`
          : `Estimated cost to you: clinic about ${cur} ${clinic} vs home visit about ${cur} ${home}`,
      },
    ],
    simulated: true,
  };
}

export function createLivePhoneCall({ target = 'vet', lang = 'zh', context = {}, speed = 1 } = {}) {
  const base = PHONE_AGENT_URL || '';
  const listeners = new Set();
  const timers = new Set();
  const state = { ended: false, audio: null };
  let started = false;

  const emit = (e) => {
    if (!state.ended) listeners.forEach((l) => l(e));
  };
  const wait = (ms) =>
    new Promise((resolve) => {
      const id = setTimeout(() => {
        timers.delete(id);
        resolve();
      }, ms / speed);
      timers.add(id);
    });

  // Gradium audio only with explicit consent from the page (context.gradiumConsent === true);
  // the page may withdraw or give it mid-call with setGradiumConsent().
  const voice = context.voice === 'my_voice' ? 'my_voice' : 'standard';
  let gradiumConsent = context.gradiumConsent === true;
  const gradium = createGradiumLines(base, voice, state);
  const useGradium = () => gradiumConsent && !gradium.failed && !isSpeechMuted() && typeof fetch === 'function';

  async function say(lines, i) {
    const line = lines[i];
    if (line.who === 'ai' && useGradium()) {
      const blob = await gradium.fetch(i, line.original);
      // Preload the next AI line while this one plays.
      const next = lines.findIndex((l, j) => j > i && l.who === 'ai');
      if (next >= 0 && useGradium()) gradium.fetch(next, lines[next].original);
      if (state.ended) return;
      if (await playBlob(blob, state)) return;
    }
    if (state.ended) return;
    await speak(line.original, 'de', { speed, pitch: line.who === 'callee' ? 0.8 : 1.15 });
  }

  async function run() {
    emit({ type: 'status', state: 'dialing' });
    let story;
    try {
      story = await fetchStory(base);
    } catch (err) {
      emit({ type: 'error', message: `Phone agent: ${err.message}` });
      finish();
      return;
    }
    await wait(1500);
    if (state.ended) return;
    emit({ type: 'status', state: 'connected' });

    const step = (story.steps || [])[STEP_INDEX[target] ?? 2] || { lines: [] };
    const lines = [
      { who: 'ai', original: FIRST_LINE.original, text: FIRST_LINE.text[lang] ?? FIRST_LINE.text.en },
      ...(step.lines || []).map((l) => ({
        who: /^pawse/i.test(l.speaker) ? 'ai' : 'callee',
        original: l.german,
        // The backend subtitles are English; the zh UI shows them as is rather than inventing a translation.
        text: l.subtitle,
      })),
    ];
    for (const [i, line] of lines.entries()) {
      await wait(450);
      if (state.ended) return;
      emit({ type: 'speaking', who: line.who });
      const ev = { type: 'line', who: line.who, original: line.original, text: line.text };
      if (line.who === 'callee') ev.simulated = true;
      emit(ev);
      await say(lines, i);
      if (state.ended) return;
      emit({ type: 'speaking', who: 'none' });
    }
    await wait(500);
    if (state.ended) return;
    emit({ type: 'result', ...(target === 'insurance' ? buildInsuranceResult(story, lang) : buildVetResult(story, lang, context)) });
    finish();
  }

  function finish() {
    if (state.ended) return;
    emit({ type: 'status', state: 'ended' });
    state.ended = true;
    timers.forEach(clearTimeout);
    timers.clear();
    if (state.audio) {
      try { state.audio.pause(); } catch { /* ignore */ }
      state.audio = null;
    }
    stopSpeech();
  }

  return {
    on(cb) {
      listeners.add(cb);
      return () => listeners.delete(cb);
    },
    start() {
      if (started) return;
      started = true;
      run().catch((err) => {
        emit({ type: 'error', message: String(err && err.message ? err.message : err) });
        finish();
      });
    },
    hangup: finish,
    /** Give or withdraw consent for Gradium audio for the remaining lines of this call. */
    setGradiumConsent(on) {
      gradiumConsent = on === true;
    },
  };
}
import { useEffect, useRef, useState } from 'react';
import Avatar from '../components/Avatar.jsx';
import Icon from '../components/Icon.jsx';
import { createPhoneCall } from '../agents/index.js';
import { validateResult } from '../contracts.js';

function fmt(sec) {
  return `${String(Math.floor(sec / 60)).padStart(2, '0')}:${String(sec % 60).padStart(2, '0')}`;
}

function ResultCard({ t, target, result }) {
  if (target === 'vet') {
    return (
      <div className="result-card">
        <h3>✓ {t.appointment}</h3>
        {result.simulated && <span className="sim-badge">{t.simulated}</span>}
        <div className="result-big">{result.time}</div>
        <p>{result.place}</p>
        <p>
          {t.estimate}: <strong>≈ {result.currency || 'CHF'} {result.estimate}</strong>
        </p>
        {result.note && <p className="muted small">{result.note}</p>}
      </div>
    );
  }
  const cur = result.currency || 'CHF';
  return (
    <div className="result-card">
      <h3>{t.insuranceAnswer}</h3>
      {result.simulated && <span className="sim-badge">{t.simulated}</span>}
      <ul className="cov">
        {result.points.map((p, i) => (
          <li key={i} className={p.ok ? 'ok' : 'no'}>
            <span className="cov-icon" aria-hidden="true">{p.ok ? '✓' : '✕'}</span>
            <span>
              {p.text}
              {p.ref && <span className="ref">{p.ref}</span>}
            </span>
          </li>
        ))}
      </ul>
      <div className="money">
        <div>
          <span className="muted small">{t.reimbursed}</span>
          <strong>≈ {cur} {result.reimbursed}</strong>
        </div>
        <div>
          <span className="muted small">{t.outOfPocket}</span>
          <strong className="accent">≈ {cur} {result.outOfPocket}</strong>
        </div>
      </div>
    </div>
  );
}

// The owner only ever deals in English (their language): Pawse talks German with the clinic or
// insurer in the background. The screen shows progress steps, questions that need the owner's
// decision, and the result. The German transcript and audio are there on request, never in the way.
export default function PhoneCall({ t, lang, target, clinic, context, gradium, onDone }) {
  const base = t.callees[target];
  const callee = clinic
    ? { ...base, name: clinic.name, role: `${clinic.distanceKm.toFixed(1)} km` }
    : base;
  const [status, setStatus] = useState('dialing');
  const [lines, setLines] = useState([]);
  const [steps, setSteps] = useState([]); // [{ text } | { chose: label }], in call order
  const [question, setQuestion] = useState(null);
  const [speaking, setSpeaking] = useState('none');
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');
  const [secs, setSecs] = useState(0);
  const [listening, setListening] = useState(false);
  const callRef = useRef(null);
  const listRef = useRef(null);
  const resultRef = useRef(null);
  const questionRef = useRef(null);
  resultRef.current = result;
  questionRef.current = question;

  useEffect(() => {
    const call = createPhoneCall({ target, lang, context });
    callRef.current = call;
    const off = call.on((e) => {
      switch (e.type) {
        case 'status':
          setStatus(e.state);
          break;
        case 'speaking':
          setSpeaking(e.who);
          break;
        case 'line':
          setLines((p) => [...p, e]);
          break;
        case 'progress':
          setSteps((p) => [...p, { text: e.text }]);
          break;
        case 'question':
          setQuestion(e);
          break;
        case 'answered': {
          const q = questionRef.current;
          if (q && q.id === e.id) {
            const opt = q.options.find((o) => o.id === e.optionId);
            setSteps((p) => [...p, { chose: opt ? opt.label : e.optionId }]);
            setQuestion(null);
          }
          break;
        }
        case 'result': {
          const { type, ...r } = e;
          const problems = validateResult(target, r);
          if (problems.length) console.warn('[Pawse] call result violates the contract:', problems, r);
          setResult(r);
          break;
        }
        case 'error':
          setError(e.message || '');
          break;
        default:
          break;
      }
    });
    call.start();
    return () => {
      off();
      call.hangup();
    };
    // context is captured once per call on purpose
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [target, lang]);

  useEffect(() => {
    if (status !== 'connected') return undefined;
    const id = setInterval(() => setSecs((s) => s + 1), 1000);
    return () => clearInterval(id);
  }, [status]);

  useEffect(() => {
    const el = listRef.current;
    if (el) el.scrollTop = el.scrollHeight;
  }, [steps, question, result]);

  const hangup = () => {
    callRef.current && callRef.current.hangup();
    onDone(resultRef.current);
  };

  const choose = (optionId) => {
    if (question && callRef.current && callRef.current.answer) callRef.current.answer(question.id, optionId);
  };

  const toggleListen = () => {
    const next = !listening;
    setListening(next);
    callRef.current && callRef.current.setListening && callRef.current.setListening(next);
  };

  const toggleGradium = () => {
    const next = !gradium.on;
    gradium.set(next);
    callRef.current && callRef.current.setGradiumConsent && callRef.current.setGradiumConsent(next);
  };

  const live = status !== 'ended' && !result;
  const statusText = status === 'dialing' ? t.dialing : status === 'connected' ? `${t.inCall} · ${fmt(secs)}` : t.callEnded;

  return (
    <main className="pc">
      <header className="pc-head">
        <div className={`pc-callee ${speaking === 'callee' ? 'talking' : ''} ${status === 'dialing' ? 'ringing' : ''}`}>
          <span aria-hidden="true">{callee.icon}</span>
        </div>
        <h1>{callee.name}</h1>
        <p className="muted">
          {callee.role} · {statusText}
        </p>
        <span className="sim-badge">{t.simulatedCall}</span>
      </header>

      <section className="bridge" aria-label={t.bridgeNote}>
        <div className="bridge-side you">
          <span className="bridge-who">{t.you}</span>
          <strong>{t.ownerLang}</strong>
        </div>
        <div className="bridge-mid" aria-hidden="true">
          <span className={`bridge-wire ${status === 'connected' ? 'on' : ''}`} />
          <Avatar size={40} speaking={speaking === 'ai'} />
          <span className={`bridge-wire ${status === 'connected' ? 'on' : ''}`} />
        </div>
        <div className="bridge-side call">
          <span className="bridge-who">{t.onTheCall}</span>
          <strong lang="de">Deutsch</strong>
        </div>
        <p className="bridge-note">{t.bridgeNote}</p>
      </section>

      <section className="pc-lines" ref={listRef} aria-live="polite">
        <h2 className="pc-sub">{t.progressTitle}</h2>
        <ol className="steps">
          {status === 'dialing' && <li className="step now">{t.dialing}</li>}
          {steps.map((s, i) =>
            s.chose ? (
              <li key={i} className="step done you">
                {t.youChose}: <strong>{s.chose}</strong>
              </li>
            ) : (
              <li key={i} className={`step ${live && i === steps.length - 1 && !question ? 'now' : 'done'}`}>
                {s.text}
              </li>
            )
          )}
        </ol>

        {question && (
          <div className="ask-card" role="group" aria-label={t.questionTitle}>
            <h3>{t.questionTitle}</h3>
            <p>{question.text}</p>
            <div className="ask-options">
              {question.options.map((o) => (
                <button key={o.id} type="button" className="btn primary" onClick={() => choose(o.id)}>
                  {o.label}
                </button>
              ))}
            </div>
            <p className="muted small">{t.holdNote}</p>
          </div>
        )}

        {result && <ResultCard t={t} target={target} result={result} />}
        {error && <p className="pc-error">{error}</p>}

        {lines.length > 0 && (
          <details className="transcript">
            <summary>{t.transcript}</summary>
            {lines.map((l, i) => (
              <div key={i} className={`line line-${l.who}`}>
                <span className="line-who">{l.who === 'ai' ? t.pawse : callee.name}</span>
                {l.simulated && <span className="sim-badge">{t.simulated}</span>}
                <p className="line-text">{l.text}</p>
                <p className="line-original" lang="de">{l.original}</p>
              </div>
            ))}
          </details>
        )}
      </section>

      {gradium && listening && (
        <label className="pc-gradium">
          <input type="checkbox" checked={gradium.on} onChange={toggleGradium} />
          <span>
            <strong>{gradium.ownVoice ? t.gradiumOwnVoice : t.gradiumVoice}</strong>
            <span className="muted small">{t.gradiumNote}</span>
          </span>
        </label>
      )}

      <footer className="pc-foot">
        {!live ? (
          <button type="button" className="btn primary wide" onClick={() => onDone(resultRef.current)}>
            {t.backToPawse}
          </button>
        ) : (
          <div className="pc-controls">
            <button
              type="button"
              className={`pc-listen ${listening ? 'on' : ''}`}
              onClick={toggleListen}
              aria-pressed={listening}
            >
              <span className="pc-ctl">
                <Icon name={listening ? 'volume' : 'volumeOff'} />
              </span>
              <span className="small">{listening ? t.listeningIn : t.listenIn}</span>
            </button>
            <button type="button" className="pc-ctl hang" onClick={hangup} aria-label={t.hangup}>
              <Icon name="phone" size={28} style={{ transform: 'rotate(135deg)' }} />
            </button>
            <span className="pc-ctl-spacer" />
          </div>
        )}
      </footer>
    </main>
  );
}

